def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    opponent_x, opponent_y = observation['opponent_position']
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    resource_positions = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    # Find closest resource
    target = min(resource_positions, key=lambda pos: dist((x,y), pos), default=None)
    # Determine move to approach target or pursue opponent if closer
    def move_towards(target_pos):
        if not target_pos:
            return 0,0
        dx, dy = 0,0
        if target_pos[0] > x: dx=1
        elif target_pos[0]<x: dx=-1
        if target_pos[1] > y: dy=1
        elif target_pos[1]<y: dy=-1
        # Prioritize horizontal or vertical for simplicity
        if abs(target_pos[0]-x) >= abs(target_pos[1]-y):
            step = (1 if target_pos[0]>x else -1, 0)
        else:
            step = (0,1 if target_pos[1]>y else -1)
        new_x, new_y = x+step[0], y+step[1]
        if (new_x,new_y) not in obstacles and 0<=new_x<width and 0<=new_y<height:
            return step
        # fallback: try other directions
        for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx, ny = x+dx, y+dy
            if (nx,ny) not in obstacles and 0<=nx<width and 0<=ny<height:
                return (dx,dy)
        return 0,0
    # Decide move based on closest resource or pursue opponent if closer
    resource_dist = dist((x,y), target) if target else float('inf')
    opponent_dist = dist((x,y), (opponent_x, opponent_y))
    if opponent_dist < resource_dist:
        move_dx, move_dy = move_towards((opponent_x, opponent_y))
    else:
        move_dx, move_dy = move_towards(target)
    return [move_dx, move_dy]
